"""Adversarial field-catalog and browser-evidence tests; not service acceptance."""
import copy,json,base64,hashlib,tempfile,unittest,zlib,struct
from pathlib import Path
import guided_service_reading as guided
class GuidedServiceReadingTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.registry=json.loads((guided.ROOT/guided.CATALOG).read_text());cls.presentation=json.loads((guided.ROOT/guided.PRESENTATION).read_text())
    def invalid(self,mutate):
        r=copy.deepcopy(self.registry);p=copy.deepcopy(self.presentation);mutate(r,p);self.assertTrue(guided.validate_catalog(r,p))
    def test_current_static(self):self.assertEqual(guided.check(),[])
    def test_no_scope_promotion(self):self.invalid(lambda r,p:r['guided_configuration_design']['scope_boundaries'].update(product_acceptance='passed'))
    def test_counts_not_forged(self):self.invalid(lambda r,p:p['counts'].update(http_protocols=12))
    def test_internal_fields_remain_hidden(self):self.invalid(lambda r,p:p['internal_fields'][0].update(classification='required'))
    def test_unknown_configuration_ref(self):self.invalid(lambda r,p:r['guided_acceptance'][0].update(source_configuration_requirement_ids=['AI-CFG-99']))
    def test_unknown_reading_ref(self):self.invalid(lambda r,p:r['guided_acceptance'][0].update(source_reading_requirement_ids=['RW-99']))
    def test_blocker_must_explain_why(self):self.invalid(lambda r,p:next(x for x in p['services'] if x.get('preset_material_blockers'))['preset_material_blockers'][0].update(reason=''))
    def test_blocker_condition_dependency(self):self.invalid(lambda r,p:next(x for x in p['services'] if x.get('preset_material_blockers'))['preset_material_blockers'][0]['condition']['all'][0].update(field='missing'))
    def test_protocol_auth_identity(self):self.invalid(lambda r,p:p['services'][0].update(auth_kind='arbitrary'))
    def test_model_identity(self):self.invalid(lambda r,p:p['services'][0].update(model_identity='not_applicable'))
    def test_fixed_endpoint_missing(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint').pop('default_value'))
    def test_material_blocker_missing(self):self.invalid(lambda r,p:next(x for x in p['services'] if x['id']=='builtin.qwen').update(preset_material_blockers=[]))
    def test_endpoint_not_url(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint').update(default_value='not-a-url'))
    def test_fixed_field_enums(self):self.invalid(lambda r,p:p['classifications'].append('unsafe'))
    def test_official_source_empty(self):self.invalid(lambda r,p:p['sources']['deepseek'].update(ref=''))
    def test_in_requires_list(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint').update(condition={'all':[{'field':'connection_mode','op':'in','value':'custom'}]}))
    def test_brand_identity_ownership(self):self.invalid(lambda r,p:p['services'][0].update(brand_id='qwen'))
    def test_brand_default_ownership(self):self.invalid(lambda r,p:p['brands'][0].update(default_service_id='builtin.qwen'))
    def test_png_truncated_rejected(self):self.assertFalse(guided.png_valid(b'\x89PNG\r\n\x1a\n'+b'\0'*16))
    def test_node_sources_changed(self):self.assertTrue(self.evidence(lambda r:r.update(source_hashes_after={'fixture':'b'*64})))
    def test_node_sources_missing(self):self.assertTrue(self.evidence(lambda r:r.pop('source_hashes')))
    def test_regressions_required(self):self.assertTrue(self.evidence(lambda r:r.pop('regression_checks')))
    def test_regressions_cannot_skip(self):self.assertTrue(self.evidence(lambda r:r['regression_checks'][0].update(status='skipped')))
    def test_http_auth_identity_required(self):self.invalid(lambda r,p:p['services'][0].pop('auth_kind',None))
    def test_empty_any_rejected(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='api_key')['condition'].update(any=[]))
    def test_catalog_valid(self):self.assertEqual(guided.validate_catalog(self.registry,self.presentation),[])
    def test_wrong_input_shape(self):self.assertTrue(guided.validate_catalog([],[]))
    def test_current_reading_must_precede_records(self):self.invalid(lambda r,p:r['guided_configuration_design']['reading'].update(placement='before_primary_reading'))
    def test_records_default_collapsed(self):self.invalid(lambda r,p:r['guided_configuration_design']['reading'].update(default_collapsed=False))
    def test_collapse_bool_type(self):self.invalid(lambda r,p:r['guided_configuration_design']['reading'].update(default_collapsed=1))
    def test_missing_dataset(self):self.invalid(lambda r,p:r['guided_configuration_design']['reading']['secondary_regions'].pop())
    def test_no_product_promotion(self):self.invalid(lambda r,p:p.update(product_acceptance='passed'))
    def test_no_implicit_design_approval(self):self.invalid(lambda r,p:p.update(status='approved'))
    def test_missing_service(self):self.invalid(lambda r,p:p['services'].pop())
    def test_duplicate_service(self):self.invalid(lambda r,p:p['services'].__setitem__(1,copy.deepcopy(p['services'][0])))
    def test_exact_protocol_identity(self):self.invalid(lambda r,p:p['services'][0].update(protocol_id='anthropic'))
    def test_exact_profile_identity(self):self.invalid(lambda r,p:p['services'][0].update(profile_id='all-openai'))
    def test_exact_contract_revision(self):self.invalid(lambda r,p:p['services'][0].update(adapter_contract_revision=True))
    def test_narrow_purpose_set(self):self.invalid(lambda r,p:p['services'][-1].update(allowed_purposes=['translation','grammar']))
    def test_missing_brand_assignment(self):self.invalid(lambda r,p:p['brands'][0]['service_ids'].clear())
    def test_secret_mask_required(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['type']=='secret').update(masked=False))
    def test_secret_default_rejected(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['type']=='secret').update(default_value='sample-real-key'))
    def test_required_internal_field_rejected(self):self.invalid(lambda r,p:p['services'][0]['fields'].append({'id':'salt','type':'text','label':'salt','classification':'required','condition':{'all':[]},'source_refs':['registry']}))
    def test_fixed_builtin_url_not_user_required(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint').update(classification='required'))
    def test_custom_intent_required_for_url(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint').update(condition={'all':[]}))
    def test_example_model_not_default(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='model').update(default_value='example-model'))
    def test_dangling_condition_rejected(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint')['condition']['all'][0].update(field='missing'))
    def test_unknown_operator_rejected(self):self.invalid(lambda r,p:next(f for f in p['services'][0]['fields'] if f['id']=='endpoint')['condition']['all'][0].update(op='execute'))
    def test_source_required(self):self.invalid(lambda r,p:p['services'][0]['fields'][0].update(source_refs=['missing']))
    def test_local_unknown_must_block(self):self.invalid(lambda r,p:p['services'][-1].update(unknown_required_condition_blocks=False))
    def test_guided_product_not_run(self):self.invalid(lambda r,p:r['guided_acceptance'][0].update(status='passed'))
    def test_guided_fp_mapping_required(self):self.invalid(lambda r,p:r['guided_acceptance'][0].update(source_requirement_ids=[]))
    def test_guided_future_layer_required(self):self.invalid(lambda r,p:r['guided_acceptance'][0].update(verification_layers=['design']))
    def test_plan_cannot_claim_product_passed(self):self.assertTrue(guided.validate_plan((guided.ROOT/guided.PLAN).read_text().replace('not_run |','passed |',1)))
    def evidence(self,mutate=None):
        with tempfile.TemporaryDirectory() as t:
            p=Path(t)
            def chunk(kind,data):return struct.pack('>I',len(data))+kind+data+struct.pack('>I',zlib.crc32(kind+data)&0xffffffff)
            b=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',1,1,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(b'\0\xff\xff\xff\xff'))+chunk(b'IEND',b'');(p/'a.png').write_bytes(b)
            r={'regression_checks':[{'id':f'GUI{n:02d}','status':'passed','assertions':1} for n in range(1,9)],'source_hashes':{'fixture':'a'*64},'source_hashes_after':{'fixture':'a'*64},'schema_version':1,'kind':'guided_service_reading_design_verification','layer':'design','status':'passed','product_tests_executed':False,'assertions':12,'checks':[{'id':i,'status':'passed','assertions':1} for i in sorted(guided.GD_IDS)],'page_errors':[],'console_errors':[],'network_requests':[],'screenshots':[{'path':'a.png','bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'width':1,'height':1}]}
            if mutate:mutate(r)
            (p/'report.json').write_text(json.dumps(r));return guided._adapter_report(p)[1]
    def test_valid_design_evidence(self):self.assertEqual(self.evidence(),[])
    def test_missing_scenario(self):self.assertTrue(self.evidence(lambda r:r['checks'].pop()))
    def test_zero_scenario_assertions(self):self.assertTrue(self.evidence(lambda r:r['checks'][0].update(assertions=0)))
    def test_console_error_rejected(self):self.assertTrue(self.evidence(lambda r:r['console_errors'].append('error')))
    def test_network_request_rejected(self):self.assertTrue(self.evidence(lambda r:r['network_requests'].append('https://example.com')))
    def test_false_png_hash_rejected(self):self.assertTrue(self.evidence(lambda r:r['screenshots'][0].update(sha256='0'*64)))
    def test_product_evidence_rejected(self):self.assertTrue(self.evidence(lambda r:r.update(product_tests_executed=True)))
    def test_output_cannot_reuse_existing_directory(self):
        with tempfile.TemporaryDirectory(dir=guided.ROOT/'.build') as t:
            with self.assertRaises(ValueError):guided.execute(guided.ROOT,Path(t))
    def test_output_cannot_escape_build(self):
        with self.assertRaises(ValueError):guided._output_path(guided.ROOT,guided.ROOT/'reports/unsafe')
